export const LogoSymbol: React.FC<{
  size?: number | string
  className?: string
  theme?: 'dark' | 'light'
  fColor?: string
  withBackground?: boolean
}> = ({ size = 36, className = '', theme = 'light', fColor, withBackground = false }) => {
  const numericSize = typeof size === 'number' ? size : parseInt(String(size), 10) || 36
  const uid = useId().replace(/:/g, '')
  const boxGradId = `box-grad-${uid}`
  const fGradId = `f-grad-${uid}`

  // Regra unificada de cor: no dark = branco; no light = branco se caixa é azul escuro (ou gradiente se customizado)
  // Mas por regra permanente: F da caixa e a palavra Fideliza seguem a mesma resolução de cor.
  // Quando theme === 'dark', F é branco puro (#FEFEFE) e o wordmark é branco (#FFFFFF).
  // Quando theme === 'light', o wordmark e o F usam a identidade oficial.
  // Nota: o F sobre a caixa azul #012D76 -> #0283FD tem contraste perfeito em branco (#FEFEFE),
  // e no dark também fica branco. Se for passado fColor explícito ou theme customizado, respeitamos.
  const isDark = theme === 'dark'
  const resolvedFColor = fColor || (isDark ? '#FEFEFE' : '#FEFEFE')

  const svgContent = (
    <svg
      width={numericSize}
      height={numericSize}
      viewBox="30000 0 40000 36000"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      shapeRendering="geometricPrecision"
      textRendering="geometricPrecision"
      className={`shrink-0 ${!withBackground ? className : ''}`}
      aria-label="Símbolo Fideliza"
    >
      <defs>
        <linearGradient
          id={boxGradId}
          x1="43340.86"
          y1="23354.42"
          x2="63884.39"
          y2="18283.63"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" stopColor="#012D76" />
          <stop offset="1" stopColor="#0283FD" />
        </linearGradient>
        <linearGradient
          id={fGradId}
          x1="43340.86"
          y1="23354.42"
          x2="63884.39"
          y2="18283.63"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" stopColor="#012D76" />
          <stop offset="1" stopColor="#0283FD" />
        </linearGradient>
      </defs>

      {/* Bow knot (nó superior da fita em laranja #F58634) */}
      <path
        fill="#F58634"
        d="M48449.11 6311.14l2433.55 0c550.73,0 1001.31,450.59 1001.31,1001.31l0 2016.4 -4398.09 470.14 -0.03 -2.29 0 -2522.27c0,-529.82 433.47,-963.28 963.27,-963.28z"
      />

      {/* Ribbon left loop (#0283FD) */}
      <path
        fill="#0283FD"
        d="M48874.26 5754.33c-1365.83,-2808.79 -3007.83,-4581.91 -4937.14,-5277.57 -1827.17,-662.41 -3557.76,-777.67 -5026.41,591.55 -1071.27,1102.96 -1790.35,2414 -1871.37,4102.07 357.61,-1214.42 1540.95,-1738.98 3520.02,-1598.78 2073.8,174.64 4189.65,1295.51 6372.03,3913.24 77.55,-1193.85 733.56,-1761.62 1942.88,-1730.51z"
      />

      {/* Ribbon right loop (#0283FD) */}
      <path
        fill="#0283FD"
        d="M50507.25 5762.29c1365.83,-2808.79 3007.83,-4581.91 4937.14,-5277.57 1827.17,-662.41 3557.76,-777.67 5026.41,591.55 1071.27,1102.96 1790.35,2414 1871.37,4102.07 -357.61,-1214.42 -1540.95,-1738.98 -3520.02,-1598.78 -2073.8,174.64 -4189.65,1295.51 -6372.03,3913.24 -77.55,-1193.85 -733.56,-1761.62 -1942.88,-1730.51z"
      />

      {/* Ribbon dark blue side 1 (#012D76) */}
      <path
        fill="#012D76"
        d="M46621.45 8244.24l0 822.33 -3546.91 -29.64c-3548.38,-66.46 -6072.02,-1558.71 -6035.2,-3866.54 381.37,-1279.84 1652.93,-1720.12 3520.02,-1598.78 777.94,2098.29 2887.83,3617.03 6062.09,4672.64z"
      />

      {/* Ribbon dark blue side 2 (#012D76) */}
      <path
        fill="#012D76"
        d="M52760.06 8252.2l0 822.33 3546.91 -29.64c3548.38,-66.46 6072.02,-1558.71 6035.2,-3866.54 -381.37,-1279.84 -1652.93,-1720.12 -3520.02,-1598.78 -777.94,2098.29 -2887.83,3617.03 -6062.09,4672.64z"
      />

      {/* Box top fold (#0283FD) */}
      <path
        fill="#0283FD"
        d="M46621.45 9066.57l0 522.28 -4125.42 651.59c-798.34,165.94 -1422.12,510.32 -1641.49,1268.11l-4807.87 -1207.55 7066.36 -1263.73 3508.43 29.32z"
      />

      {/* Box lateral left top (#012D76) */}
      <path
        fill="#012D76"
        d="M40854.53 11508.54l0 4789.18 -4605.76 -1280.1c-578,-106.94 -833.89,-409.81 -908.75,-912.58l-7.04 -2873.48c31.08,-504.48 334.72,-832.28 713.67,-930.57l4807.87 1207.55z"
      />

      {/* Box lateral left bottom (#012D76) */}
      <path
        fill="#012D76"
        d="M40854.53 17030.25l0 12751.77 -3463.13 -1668.93c-592.89,-280.02 -881.35,-877.75 -928.89,-1361.71l0 -11080.1 4392.02 1358.97z"
      />

      {/* Box main front face (gradient #012D76 -> #0283FD) */}
      <path
        fill={`url(#${boxGradId})`}
        d="M43085.51 30781.72l29.35 -18082.72c72.46,-936.7 691.21,-1451.54 1655.15,-1642.36l14321.66 -1625.92c186.09,-32.35 376.97,-33.67 572.43,-5.12l3473.59 770.79c614.5,107.08 938.32,442.18 1002.06,981.23l0 3093.21c-54.8,481.93 -300.18,828.9 -873.33,943.66 -716.79,263.58 -613.93,341 -3638.51,771.65l3327.6 -289.72 46.45 11368.74c-108.72,932.56 -569.44,1599.06 -1518.17,1896.7l-14144.23 3188.32c-469.7,113.82 -929.35,117.1 -1374.89,-34.8l-2879.14 -1333.67z"
      />

      {/* Letra 'F' na face da caixa (convertida fielmente para path vetorial) */}
      <g transform="matrix(1.10504 0 -0.178123 1 -28727.1 137568)">
        <g transform="translate(48822.26, -107574.09) scale(26.09044, -26.09044)">
          <path fill={resolvedFColor} d={GLYPH_F_PATH} />
        </g>
      </g>
    </svg>
  )

  if (withBackground) {
    return (
      <div
        style={{ width: numericSize * 1.25, height: numericSize * 1.25 }}
        className={`rounded-2xl bg-blue-50/80 dark:bg-slate-900/80 border border-blue-200/60 dark:border-slate-800 flex items-center justify-center shrink-0 shadow-xs ${className}`}
        aria-label="Símbolo Fideliza"
      >
        {svgContent}
      </div>
    )
  }

  return svgContent
}

/**
 * Wordmark oficial "Fideliza" diretamente com os paths vetoriais do CorelDRAW
 */
export const LogoWordmark: React.FC<{
  height?: number | string
  className?: string
  theme?: 'dark' | 'light'
}> = ({ height = 28, className = '', theme = 'light' }) => {
  const numericHeight = typeof height === 'number' ? height : parseInt(String(height), 10) || 28
  const width = Math.round(numericHeight * 4.4)
  const uid = useId().replace(/:/g, '')
  const wordGradId = `word-grad-${uid}`
  const isDark = theme === 'dark'

  return (
    <svg
      width={width}
      height={numericHeight}
      viewBox="0 34000 100297.75 23000"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      shapeRendering="geometricPrecision"
      textRendering="geometricPrecision"
      className={`shrink-0 ${className}`}
      aria-label="Fideliza"
    >
      <defs>
        <linearGradient
          id={wordGradId}
          x1="29749.26"
          y1="71640.06"
          x2="70548.49"
          y2="20926.35"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" stopColor="#012D76" />
          <stop offset="1" stopColor="#0283FD" />
        </linearGradient>
      </defs>

      {/* Pingos dos 'i's em laranja (#F58634) ou branco se dark */}
      <path fill={isDark ? '#FFFFFF' : '#F58634'} d={WORDMARK_I_DOT_1} />
      <path fill={isDark ? '#FFFFFF' : '#F58634'} d={WORDMARK_I_DOT_2} />

      {/* Letras Fideliza em gradiente azul ou branco no dark */}
      <path fill={isDark ? '#FFFFFF' : `url(#${wordGradId})`} d={WORDMARK_LETTERS} />
    </svg>
  )
}

export const Logo: React.FC<LogoProps> = ({
  variant = 'horizontal',
  theme = 'light',
  size = 'md',
  className = '',
  showTagline = false,
}) => {
  const isDark = theme === 'dark'
  const subtitleColor = isDark ? 'text-slate-400' : 'text-slate-500'

  const dimensions = {
    sm: { symbolSize: 32, wordmarkHeight: 22, subtitle: 'text-[9px]' },
    md: { symbolSize: 40, wordmarkHeight: 28, subtitle: 'text-[10px]' },
    lg: { symbolSize: 52, wordmarkHeight: 36, subtitle: 'text-xs' },
    xl: { symbolSize: 64, wordmarkHeight: 44, subtitle: 'text-xs sm:text-sm' },
  }[size]

  if (variant === 'symbol') {
    return <LogoSymbol size={dimensions.symbolSize} theme={theme} className={className} />
  }

  if (variant === 'badge') {
    return (
      <LogoSymbol
        size={dimensions.symbolSize}
        theme={theme}
        withBackground={true}
        className={className}
      />
    )
  }

  if (variant === 'full') {
    return (
      <div className={`flex flex-col items-center text-center gap-2 select-none ${className}`}>
        <LogoSymbol size={dimensions.symbolSize * 1.3} theme={theme} />
        <div className="flex flex-col items-center leading-tight">
          <LogoWordmark height={dimensions.wordmarkHeight} theme={theme} />
          {showTagline && (
            <span
              className={`font-semibold uppercase tracking-wider mt-1 ${
                showTagline ? 'text-[#F58634]' : subtitleColor
              } ${dimensions.subtitle}`}
            >
              Programa de Fidelidade
            </span>
          )}
        </div>
      </div>
    )
  }

  // Horizontal (default): Símbolo + Wordmark lado a lado
  return (
    <div className={`inline-flex items-center gap-3 select-none ${className}`}>
      <LogoSymbol size={dimensions.symbolSize} theme={theme} />
      <div className="flex flex-col justify-center leading-none">
        <LogoWordmark height={dimensions.wordmarkHeight} theme={theme} />
        {showTagline && (
          <span
            className={`font-semibold uppercase tracking-wider mt-1 ${subtitleColor} ${dimensions.subtitle}`}
          >
            Programa de Fidelidade
          </span>
        )}
      </div>
    </div>
  )
}

export default Logo
